<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Canvas Billiards</title>
<style>
  * { box-sizing: border-box; }
  body {
    margin: 0; min-height: 100vh; display: grid; place-items: center;
    background: radial-gradient(circle at top, #263445, #10151c 70%);
    color: #f4ead0; font: 16px system-ui, sans-serif;
  }
  .game { width: min(960px, 96vw); text-align: center; }
  h1 { margin: 0 0 8px; font: 700 24px Georgia, serif; letter-spacing: .08em; }
  canvas {
    width: 100%; height: auto; display: block; border-radius: 16px;
    background: #123e2b; box-shadow: 0 16px 40px #000b, inset 0 0 0 2px #b88343;
    touch-action: none;
  }
  .bar { display: flex; justify-content: center; align-items: center; gap: 16px; margin-top: 12px; }
  button {
    border: 1px solid #d6ad68; border-radius: 7px; padding: 8px 16px;
    color: #fff5de; background: linear-gradient(#795228, #422811); cursor: pointer;
    font-weight: 700;
  }
  button:hover { filter: brightness(1.15); }
  .help { margin: 0; color: #d9d1bd; font-size: 14px; }
</style>
</head>
<body>
<div class="game">
  <h1>CANVAS BILLIARDS</h1>
  <canvas id="table" width="900" height="500" aria-label="Playable billiards table"></canvas>
  <div class="bar">
    <button id="rack">Reset / Rack</button>
    <p class="help">Press the white ball, drag back to aim and set power, then release to shoot.</p>
  </div>
</div>
<script>
(() => {
  const canvas = document.getElementById("table");
  const ctx = canvas.getContext("2d");
  const W = 900, H = 500, R = 12;
  const pocketRadius = 25;
  const pockets = [
    [0, 0], [W / 2, 0], [W, 0],
    [0, H], [W / 2, H], [W, H]
  ];
  let balls = [];
  let running = true, raf = 0, lastTime = 0;
  let dragging = false, dragPoint = null;

  function rackBalls() {
    const list = [{ x: 205, y: H / 2, cue: true }];
    const colors = [1, 9, 2, 10, 8, 3, 11, 4, 12, 5, 13, 6, 14, 7, 15];
    let n = 0, startX = 650, gap = R * 2 + 0.35;
    for (let row = 0; row < 5; row++) {
      for (let col = 0; col <= row; col++) {
        list.push({
          x: startX + row * gap * Math.sqrt(3) / 2,
          y: H / 2 + (col - row / 2) * gap,
          cue: false, number: colors[n++]
        });
      }
    }
    return list;
  }

  function reset(input) {
    balls = (input || []).map(b => ({
      x: Number(b.x), y: Number(b.y),
      vx: Number(b.vx) || 0, vy: Number(b.vy) || 0,
      cue: b.cue === true, potted: false, number: b.number
    }));
    dragging = false;
    draw();
  }

  function isInPocket(b) {
    for (const p of pockets) {
      const dx = b.x - p[0], dy = b.y - p[1];
      if (dx * dx + dy * dy <= pocketRadius * pocketRadius) return true;
    }
    return false;
  }

  function advance(dt) {
    const pieces = Math.max(1, Math.ceil(dt * 240));
    const h = dt / pieces;
    const friction = 0.992; // retained per 1/60 second

    for (let tick = 0; tick < pieces; tick++) {
      for (const b of balls) {
        if (b.potted) continue;
        b.x += b.vx * h;
        b.y += b.vy * h;

        if (isInPocket(b)) {
          b.potted = true; b.vx = 0; b.vy = 0;
          continue;
        }

        if (b.x < R) { b.x = R; if (b.vx < 0) b.vx = -b.vx; }
        if (b.x > W - R) { b.x = W - R; if (b.vx > 0) b.vx = -b.vx; }
        if (b.y < R) { b.y = R; if (b.vy < 0) b.vy = -b.vy; }
        if (b.y > H - R) { b.y = H - R; if (b.vy > 0) b.vy = -b.vy; }

        const damp = Math.pow(friction, h * 60);
        b.vx *= damp; b.vy *= damp;
        if (Math.hypot(b.vx, b.vy) < 1.2) { b.vx = 0; b.vy = 0; }
      }

      for (let pass = 0; pass < 2; pass++) {
        for (let i = 0; i < balls.length; i++) {
          const a = balls[i];
          if (a.potted) continue;
          for (let j = i + 1; j < balls.length; j++) {
            const b = balls[j];
            if (b.potted) continue;
            let dx = b.x - a.x, dy = b.y - a.y;
            let d2 = dx * dx + dy * dy, d = Math.sqrt(d2);
            if (d >= R * 2) continue;
            if (d < 0.00001) { dx = 1; dy = 0; d = 1; }
            const nx = dx / d, ny = dy / d;
            const overlap = R * 2 - d;
            a.x -= nx * overlap / 2; a.y -= ny * overlap / 2;
            b.x += nx * overlap / 2; b.y += ny * overlap / 2;

            const relativeNormal = (a.vx - b.vx) * nx + (a.vy - b.vy) * ny;
            if (relativeNormal > 0) {
              // Equal masses, coefficient of restitution 1.
              a.vx -= relativeNormal * nx; a.vy -= relativeNormal * ny;
              b.vx += relativeNormal * nx; b.vy += relativeNormal * ny;
            }
          }
        }
      }
    }
  }

  function step(dt) {
    if (Number.isFinite(dt) && dt > 0) advance(Math.min(dt, 2));
    draw();
  }

  function shoot(vx, vy) {
    const cue = balls.find(b => b.cue && !b.potted);
    if (!cue) return;
    if (balls.some(b => !b.potted && Math.hypot(b.vx, b.vy) > 2)) return;
    cue.vx = Number(vx) || 0;
    cue.vy = Number(vy) || 0;
  }

  function drawBall(b) {
    const palette = ["#f2d04b","#2865ad","#bd2631","#69338c","#dc702a","#26743b","#7c2225","#151515"];
    let color = b.cue ? "#f7f4e8" : palette[((b.number || 1) - 1) % palette.length];
    ctx.beginPath(); ctx.arc(b.x + 2, b.y + 3, R, 0, Math.PI * 2);
    ctx.fillStyle = "#0007"; ctx.fill();
    ctx.beginPath(); ctx.arc(b.x, b.y, R, 0, Math.PI * 2);
    ctx.fillStyle = color; ctx.fill();
    ctx.strokeStyle = "#ffffff99"; ctx.lineWidth = 1; ctx.stroke();
    ctx.beginPath(); ctx.arc(b.x - R * .3, b.y - R * .35, R * .24, 0, Math.PI * 2);
    ctx.fillStyle = "#fff8"; ctx.fill();
    if (!b.cue && b.number) {
      ctx.beginPath(); ctx.arc(b.x, b.y, R * .46, 0, Math.PI * 2);
      ctx.fillStyle = "#f7f0d9"; ctx.fill();
      ctx.fillStyle = "#222"; ctx.font = "bold 9px sans-serif";
      ctx.textAlign = "center"; ctx.textBaseline = "middle"; ctx.fillText(b.number, b.x, b.y + .5);
    }
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = "#7a4a20"; ctx.fillRect(0, 0, W, H);
    ctx.fillStyle = "#173d29"; ctx.fillRect(18, 18, W - 36, H - 36);
    ctx.fillStyle = "#174a32"; ctx.fillRect(R, R, W - 2 * R, H - 2 * R);
    ctx.strokeStyle = "#c8944f"; ctx.lineWidth = 5;
    ctx.strokeRect(10, 10, W - 20, H - 20);
    for (const [x, y] of pockets) {
      ctx.beginPath(); ctx.arc(x, y, pocketRadius, 0, Math.PI * 2);
      ctx.fillStyle = "#080909"; ctx.fill();
      ctx.strokeStyle = "#42200d"; ctx.lineWidth = 3; ctx.stroke();
    }
    if (dragging) {
      const cue = balls.find(b => b.cue && !b.potted);
      if (cue) {
        const dx = cue.x - dragPoint.x, dy = cue.y - dragPoint.y;
        ctx.setLineDash([7, 6]); ctx.lineWidth = 2; ctx.strokeStyle = "#f8edc8cc";
        ctx.beginPath(); ctx.moveTo(cue.x, cue.y);
        ctx.lineTo(cue.x + dx * 2.2, cue.y + dy * 2.2); ctx.stroke();
        ctx.setLineDash([]);
      }
    }
    for (const b of balls) if (!b.potted) drawBall(b);
  }

  function frame(t) {
    if (!running) return;
    if (lastTime) advance(Math.min((t - lastTime) / 1000, 0.05));
    lastTime = t; draw(); raf = requestAnimationFrame(frame);
  }

  function point(e) {
    const r = canvas.getBoundingClientRect();
    return { x: (e.clientX - r.left) * W / r.width, y: (e.clientY - r.top) * H / r.height };
  }
  canvas.addEventListener("pointerdown", e => {
    const p = point(e), cue = balls.find(b => b.cue && !b.potted);
    if (cue && !balls.some(b => !b.potted && Math.hypot(b.vx, b.vy) > 2) &&
        Math.hypot(p.x - cue.x, p.y - cue.y) <= R * 2) {
      dragging = true; dragPoint = p; canvas.setPointerCapture(e.pointerId); draw();
    }
  });
  canvas.addEventListener("pointermove", e => { if (dragging) { dragPoint = point(e); draw(); } });
  canvas.addEventListener("pointerup", e => {
    if (!dragging) return;
    const p = point(e), cue = balls.find(b => b.cue && !b.potted);
    dragging = false;
    if (cue) {
      const dx = cue.x - p.x, dy = cue.y - p.y, length = Math.hypot(dx, dy);
      if (length > 3) {
        const power = Math.min(1550, length * 7);
        shoot(dx / length * power, dy / length * power);
      }
    }
    draw();
  });
  canvas.addEventListener("pointercancel", () => { dragging = false; draw(); });
  document.getElementById("rack").addEventListener("click", () => reset(rackBalls()));

  window.sim = {
    W, H, R, reset, step, state: () => balls.map(b => ({
      x: b.x, y: b.y, vx: b.vx, vy: b.vy, potted: b.potted, cue: b.cue
    })), shoot,
    pause: () => { running = false; cancelAnimationFrame(raf); },
    resume: () => { if (!running) { running = true; lastTime = 0; raf = requestAnimationFrame(frame); } }
  };

  reset(rackBalls());
  raf = requestAnimationFrame(frame);
})();
</script>
</body>
</html>
